import{_ as p,a0 as o,w as r,s as d,ao as l,I as n,x as e,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"內容安全策略（CSP），防禦 XSS 攻擊的好助手 | LCTT x X-CMD","titleTemplate":false,"description":"內容安全策略（CSP），防禦 XSS 攻擊的好助手 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"內容安全策略（CSP），防禦 XSS 攻擊的好助手 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"內容安全策略（CSP），防禦 XSS 攻擊的好助手 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160912 Content Security Policy, Your Future Best Friend","title":"內容安全策略（CSP），防禦 XSS 攻擊的好助手","tag":"201610","desc":""},"relativePath":"201610/20160912 Content Security Policy, Your Future Best Friend.md","filePath":"[post].md"}'),c={name:"201610/20160912 Content Security Policy, Your Future Best Friend.md"};function g(h,s,u,f,S,C){const a=o("Link");return r(),d("div",null,[s[39]||(s[39]=l(`<h1 id="內容安全策略-csp-防禦-xss-攻擊的好助手" tabindex="-1">內容安全策略（CSP），防禦 XSS 攻擊的好助手 <a class="header-anchor" href="#內容安全策略-csp-防禦-xss-攻擊的好助手" aria-label="Permalink to “內容安全策略（CSP），防禦 XSS 攻擊的好助手”">​</a></h1><p>很久之前，我的個人網站被攻擊了。我不知道它是如何發生的，但它確實發生了。幸運的是，攻擊帶來的破壞是很小的：一小段 JavaScript 被注入到了某些頁面的底部。我更新了 FTP 和其它的口令，清理了一些文件，事情就這樣結束了。</p><p>有一點使我很惱火：在當時，還沒有一種簡便的方案能夠使我知道那裏有問題，更重要的是能夠保護網站的訪客不被這段惱人的代碼所擾。</p><p>現在有一種方案出現了，這種技術在上述兩方面都十分的成功。它就是內容安全策略（content security policy，CSP）。</p><h3 id="什麼是-csp" tabindex="-1">什麼是 CSP? <a class="header-anchor" href="#什麼是-csp" aria-label="Permalink to “什麼是 CSP?”">​</a></h3><p>其核心思想十分簡單：網站通過發送一個 CSP 頭部，來告訴瀏覽器什麼是被授權執行的與什麼是需要被禁止的。</p><p>這裏有一個 PHP 的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>    header(&quot;Content-Security-Policy: &lt;your directives&gt;&quot;);</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><h4 id="一些指令" tabindex="-1">一些指令 <a class="header-anchor" href="#一些指令" aria-label="Permalink to “一些指令”">​</a></h4><p>你可以定義一些全局規則或者定義一些涉及某一類資源的規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>default-src &#39;self&#39; ;</span></span>
<span class="line"><span>     # self = 同端口，同域名，同協議 =&gt; 允許</span></span></code></pre></div><p>基礎參數是 <code>default-src</code>：如果沒有為某一類資源設置指令規則，那麼瀏覽器就會使用這個默認參數值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>script-src &#39;self&#39; www.google-analytics.com ;</span></span>
<span class="line"><span>     # 來自這些域名的 JS 文件 =&gt; 允許</span></span></code></pre></div><p>在這個例子中，我們已經授權了 www.google-analytics.com 這個域名來源的 JavaScript 文件使用到我們的網站上。我們也添加了 <code>&#39;self&#39;</code> 這個關鍵詞；如果我們通過 <code>script-src</code> 來重新設置其它的規則指令，它將會覆蓋 <code>default-src</code> 規則。</p>`,14)),n("p",null,[s[5]||(s[5]=e("如果沒有指明協議（scheme）或端口，它就會強制選擇與當前頁面相同的協議或端口。這樣做防止了混合內容（LCTT 譯註：混合內容指 HTTPS 頁面中也有非 HTTPS 資源，可參見： ",-1)),t(a,{href:"https://developer.mozilla.org/zh-CN/docs/Security/MixedContent"},{default:i(()=>[...s[0]||(s[0]=[e("https://developer.mozilla.org/zh-CN/docs/Security/MixedContent",-1)])]),_:1}),s[6]||(s[6]=e(" ）。如果頁面是 ",-1)),t(a,{href:"https://example.com"},{default:i(()=>[...s[1]||(s[1]=[e("https://example.com",-1)])]),_:1}),s[7]||(s[7]=e("，那麼你將無法加載 ",-1)),t(a,{href:"http://www.google-analytics.com/file.js"},{default:i(()=>[...s[2]||(s[2]=[e("http://www.google-analytics.com/file.js",-1)])]),_:1}),s[8]||(s[8]=e(" 因為它已經被禁止了（協議不匹配）。然而，有一個例外就是協議的提升是被允許的。如果 ",-1)),t(a,{href:"http://example.com"},{default:i(()=>[...s[3]||(s[3]=[e("http://example.com",-1)])]),_:1}),s[9]||(s[9]=e(" 嘗試加載 ",-1)),t(a,{href:"https://www.google-analytics.com/file.js%EF%BC%8C%E6%8E%A5%E7%9D%80%E5%8D%94%E8%AD%B0%E6%88%96%E7%AB%AF%E5%8F%A3%E5%85%81%E8%A8%B1%E8%A2%AB%E6%9B%B4%E6%94%B9%E4%BB%A5%E4%BE%BF%E5%8D%94%E8%AD%B0%E7%9A%84%E6%8F%90%E5%8D%87%E3%80%82"},{default:i(()=>[...s[4]||(s[4]=[e("https://www.google-analytics.com/file.js，接着協議或端口允許被更改以便協議的提升。",-1)])]),_:1})]),s[40]||(s[40]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>style-src &#39;self&#39; data: ;</span></span>
<span class="line"><span>     # Data-Uri 嵌入 CSS =&gt; 允許</span></span></code></pre></div><p>在這個例子中，關鍵詞 <code>data:</code> 授權了在 CSS 文件中 data 內嵌內容。</p><p>在 CSP 1 規範下，你也可以設置如下規則：</p><ul><li><code>img-src</code> 有效的圖片來源</li><li><code>connect-src</code> 應用於 XMLHttpRequest（AJAX），WebSocket 或 EventSource</li><li><code>font-src</code> 有效的字體來源</li><li><code>object-src</code> 有效的插件來源（例如，<code>&lt;object&gt;</code>，<code>&lt;embed&gt;</code>，<code>&lt;applet&gt;</code>）</li><li><code>media-src</code> 有效的 <code>&lt;audio&gt;</code> 和 <code>&lt;video&gt;</code> 來源</li></ul><p>CSP 2 規範包含了如下規則：</p><ul><li><code>child-src</code> 有效的 web workers 和 元素來源，如 <code>&lt;frame&gt;</code> 和 <code>&lt;iframe&gt;</code> （這個指令用來替代 CSP 1 中廢棄了的 <code>frame-src</code> 指令）</li><li><code>form-action</code> 可以作為 HTML <code>&lt;form&gt;</code> 的 action 的有效來源</li><li><code>frame-ancestors</code> 使用 <code>&lt;frame&gt;</code>，<code>&lt;iframe&gt;</code>，<code>&lt;object&gt;</code>，<code>&lt;embed&gt;</code> 或 <code>&lt;applet&gt;</code> 內嵌資源的有效來源</li><li><code>upgrade-insecure-requests</code> 命令用户代理來重寫 URL 協議，將 HTTP 改到 HTTPS （為一些需要重寫大量陳舊 URL 的網站提供了方便）。</li></ul><p>為了更好的向後兼容一些廢棄的屬性，你可以簡單的複製當前指令的內容同時為那個廢棄的指令創建一個相同的副本。例如，你可以複製 <code>child-src</code> 的內容同時在 <code>frame-src</code> 中添加一份相同的副本。</p><p>CSP 2 允許你添加路徑到白名單中（CSP 1 只允許域名被添加到白名單中）。因此，相較於將整個 www.foo.com 域添加到白名單，你可以通過添加 www.foo.com/some/folder 這樣的路徑到白名單中來作更多的限制。這個需要瀏覽器中 CSP 2 的支持，但它很明顯更安全。</p><h4 id="一個例子" tabindex="-1">一個例子 <a class="header-anchor" href="#一個例子" aria-label="Permalink to “一個例子”">​</a></h4>`,9)),n("p",null,[s[11]||(s[11]=e("我為 Web 2015 巴黎大會上我的演講 “",-1)),t(a,{href:"https://rocssti.net/en/example-csp-paris-web2015"},{default:i(()=>[...s[10]||(s[10]=[e("CSP in Action",-1)])]),_:1}),s[12]||(s[12]=e("”製作了一個簡單的例子。",-1))]),s[41]||(s[41]=l(`<p>在沒有 CSP 的情況下，頁面展示如下圖所示：</p><p><img src="https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing1b-500.jpg" alt=""></p><p>不是十分優美。要是我們啓用瞭如下的 CSP 指令又會怎樣呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>    header(&quot;Content-Security-Policy: </span></span>
<span class="line"><span>      default-src &#39;self&#39; ;</span></span>
<span class="line"><span>      script-src &#39;self&#39; www.google-analytics.com stats.g.doubleclick.net ; </span></span>
<span class="line"><span>      style-src &#39;self&#39; data: ;</span></span>
<span class="line"><span>      img-src &#39;self&#39; www.google-analytics.com stats.g.doubleclick.net data: ;</span></span>
<span class="line"><span>      frame-src &#39;self&#39; ;&quot;);</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>瀏覽器將會作什麼呢？它會（非常嚴格的）在 CSP 基礎規則之下應用這些指令，這意味着<strong>任何沒有在 CSP 指令中被授權允許的都將會被禁止</strong>（“blocked” 指的是不被執行、不被顯示並且不被使用在網站中）。</p><p>在 CSP 的默認設置中，內聯腳本和樣式是不被授權的，意味着每一個 <code>&lt;script&gt;</code>，<code>onclick</code> 事件屬性或 <code>style</code> 屬性都將會被禁止。你可以使用 <code>style-src &#39;unsafe-inline&#39; ;</code> 指令來授權使用內聯 CSS。</p><p>在一個支持 CSP 的現代瀏覽器中，上述示例看起來如下圖：</p><p><img src="https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing5-500.jpg" alt=""></p><p>發生了什麼？瀏覽器應用了指令並且拒絕了所有沒有被授權的內容。它在瀏覽器調試終端中發送了這些通知：</p><p><img src="https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing2-500.jpg" alt=""></p>`,10)),n("p",null,[s[14]||(s[14]=e("如果你依然不確定 CSP 的價值，請看一下 Aaron Gustafson 文章 “",-1)),t(a,{href:"https://www.aaron-gustafson.com/notebook/more-proof-we-dont-control-our-web-pages/"},{default:i(()=>[...s[13]||(s[13]=[e("More Proof We Don't Control Our Web Pages",-1)])]),_:1}),s[15]||(s[15]=e("”。",-1))]),s[42]||(s[42]=l('<p>當然，你可以使用比我們在示例中提供的更嚴格的指令：</p><ul><li>設置 <code>default-src</code> 為 &#39;none&#39;</li><li>為每條規則指定你的設置</li><li>為請求的文件指定它的絕對路徑</li><li>等</li></ul><h3 id="更多關於-csp-的信息" tabindex="-1">更多關於 CSP 的信息 <a class="header-anchor" href="#更多關於-csp-的信息" aria-label="Permalink to “更多關於 CSP 的信息”">​</a></h3><h4 id="支持" tabindex="-1">支持 <a class="header-anchor" href="#支持" aria-label="Permalink to “支持”">​</a></h4>',4)),n("p",null,[s[17]||(s[17]=e("CSP 不是一個需要複雜的配置才能正常工作的每日構建特性。CSP 1 和 2 是候選推薦標準！",-1)),t(a,{href:"http://caniuse.com/#feat=contentsecuritypolicy"},{default:i(()=>[...s[16]||(s[16]=[e("瀏覽器可以非常完美的支持 CSP 1",-1)])]),_:1}),s[18]||(s[18]=e("。",-1))]),s[43]||(s[43]=n("p",null,[n("img",{src:"https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing3-500.jpg",alt:""})],-1)),n("p",null,[t(a,{href:"http://caniuse.com/#feat=contentsecuritypolicy2"},{default:i(()=>[...s[19]||(s[19]=[e("CSP 2 是較新的規範",-1)])]),_:1}),s[20]||(s[20]=e("，因此對它的支持會少那麼一點。",-1))]),s[44]||(s[44]=l(`<p><img src="https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing4-500.jpg" alt=""></p><p>現在 CSP 3 還是一個早期草案，因此還沒有被支持，但是你依然可以使用 CSP 1 和 2 來做一些重大的事。</p><h4 id="其他需要考慮的因素" tabindex="-1">其他需要考慮的因素 <a class="header-anchor" href="#其他需要考慮的因素" aria-label="Permalink to “其他需要考慮的因素”">​</a></h4><p>CSP 被設計用來降低跨站腳本攻擊（XSS）的風險，這就是不建議開啓內聯腳本和 <code>script-src</code> 指令的原因。Firefox 對這個問題做了很好的説明：在瀏覽器中，敲擊 <code>Shift + F2</code> 並且鍵入 <code>security csp</code>，它就會向你展示指令和對應的建議。這裏有一個在 Twitter 網站中應用的例子：</p><p><img src="https://www.smashingmagazine.com/wp-content/uploads/2016/09/csp_smashing6b-500.jpg" alt=""></p><p>如果你確實需要使用內聯腳本和樣式的話，另一種可能就是生成一份散列值。例如，我們假定你需要使用如下的內聯腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script&gt;alert(&#39;Hello, world.&#39;);&lt;/script&gt;</span></span></code></pre></div><p>你應該在 <code>script-src</code> 指令中添加 <code>sha256-qznLcsROx4GACP2dm0UCKCzCG-HiZ1guq6ZZDob_Tng=</code> 作為有效來源。這個散列值用下面的 PHP 腳本執行獲得的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>    echo base64_encode(hash(&#39;sha256&#39;, &quot;alert(&#39;Hello, world.&#39;);&quot;, true));</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>我在前文中説過 CSP 被設計用來降低 XSS 風險，我還得加上“……與降低未經請求內容的風險。”伴隨着 CSP 的使用，你必須<strong>知道你內容的來源是哪裏</strong>與<strong>它們在你的前端都作了些什麼</strong>（內聯樣式，等）。CSP 同時可以幫助你讓貢獻者、開發人員和其他人員來遵循你內容來源的規則！</p><p>現在你的問題就只是，“不錯，這很好，但是我們如何在生產環境中使用它呢？”</p><h3 id="如何在現實世界中使用它" tabindex="-1">如何在現實世界中使用它 <a class="header-anchor" href="#如何在現實世界中使用它" aria-label="Permalink to “如何在現實世界中使用它”">​</a></h3><p>想要在第一次使用 CSP 之後就失望透頂的方法就是在生產環境中測試。不要想當然的認為，“這會很簡單。我的代碼是完美並且相當清晰的。”不要這樣作。我這樣幹過。相信我，這相當的蠢。</p><p>正如我之前説明的，CSP 指令由 CSP 頭部來激活，這中間沒有過渡階段。你恰恰就是其中的薄弱環節。你可能會忘記授權某些東西或者遺忘了你網站中的一小段代碼。CSP 不會饒恕你的疏忽。然而，CSP 的兩個特性將這個問題變得相當的簡單。</p><h4 id="report-uri" tabindex="-1">report-uri <a class="header-anchor" href="#report-uri" aria-label="Permalink to “report-uri”">​</a></h4><p>還記得 CSP 發送到終端中的那些通知麼？<code>report-uri</code> 指令可以被用來告訴瀏覽器發送那些通知到指定的地址。報告以 JSON 格式送出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>report-uri /csp-parser.php ;</span></span></code></pre></div><p>因此，我們可以在 csp-parser.php 文件中處理有瀏覽器送出的數據。這裏有一個由 PHP 實現的最基礎的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$data = file_get_contents(&#39;php://input&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if ($data = json_decode($data, true)) {</span></span>
<span class="line"><span>     $data = json_encode(</span></span>
<span class="line"><span>      $data,</span></span>
<span class="line"><span>      JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES</span></span>
<span class="line"><span>      );</span></span>
<span class="line"><span>     mail(EMAIL, SUBJECT, $data);</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>這個通知將會被轉換成為一封郵件。在開發過程中，你可能不會需要比這更復雜的其它東西。</p><p>對於一個生產環境（或者是一個有較多訪問的開發環境），你應該使用一種比郵件更好的收集信息的方式，因為這種方式在節點上沒有驗證和速率限制，並且 CSP 可能變得亂鬨鬨的。只需想像一個會產生 100 個 CSP 通知（例如，一個從未授權來源展示圖片的腳本）並且每天會被瀏覽 100 次的頁面，那你就會每天收到 10000 個通知啊！</p>`,21)),n("p",null,[s[22]||(s[22]=e("例如 ",-1)),t(a,{href:"https://report-uri.io/"},{default:i(()=>[...s[21]||(s[21]=[e("report-uri.io",-1)])]),_:1}),s[23]||(s[23]=e(" 這樣的服務可以用來簡化你的通知管理。你也可以在 GitHub上看一些另外的使用 ",-1)),s[24]||(s[24]=n("code",null,"report-uri",-1)),s[25]||(s[25]=e(" （與資料庫搭配，添加一些優化，等）的簡單例子。",-1))]),s[45]||(s[45]=l(`<h3 id="report-only" tabindex="-1">report-only <a class="header-anchor" href="#report-only" aria-label="Permalink to “report-only”">​</a></h3><p>正如我們所見的，最大的問題就是在使用和不使用 CSP 之間沒有中間地帶。然而，一個名為 <code>report-only</code> 的特性會發送一個稍有不同的頭部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>    header(&quot;Content-Security-Policy-Report-Only: &lt;your directives&gt;&quot;);</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>總的來説，這個頭部就是告訴瀏覽器，“表現得似乎所有的 CSP 指令都被應用了，但是不禁止任何東西。只是發送通知給自己。”這是一種相當棒的測試指令的方式，避免了任何有價值的東西被禁止的風險。</p><p>在 <code>report-only</code> 和 <code>report-uri</code> 的幫助下你可以毫無風險的測試 CSP 指令，並且可以實時的監控網站上一切與 CSP 相關的內容。這兩個特性對部署和維護 CSP 來説真是相當的有用！</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><h4 id="為什麼-csp-很酷" tabindex="-1">為什麼 CSP 很酷 <a class="header-anchor" href="#為什麼-csp-很酷" aria-label="Permalink to “為什麼 CSP 很酷”">​</a></h4><p>CSP 對你的用户來説是尤其重要的：他們在你的網站上不再需要遭受任何的未經請求的腳本，內容或 XSS 的威脅了。</p><p>對於網站維護者來説 CSP 最重要的優勢就是可感知。如果你對圖片來源設置了嚴格的規則，這時一個腳本小子嘗試在你的網站上插入一張未授權來源的圖片，那麼這張圖片就會被禁止，並且你會在第一時間收到提醒。</p><p>開發者也需要確切的知道他們的前端代碼都在做些什麼，CSP 可以幫助他們掌控一切。會促使他們去重構他們代碼中的某些部分（避免內聯函數和樣式，等）並且促使他們遵循最佳實踐。</p><h4 id="如何讓-csp-變得更酷" tabindex="-1">如何讓 CSP 變得更酷 <a class="header-anchor" href="#如何讓-csp-變得更酷" aria-label="Permalink to “如何讓 CSP 變得更酷”">​</a></h4><p>諷刺的是，CSP 在一些瀏覽器中過分的高效了，在和書籤欄小程序一起使用時會產生一些 bug。因此，不要更新你的 CSP 指令來允許書籤欄小程序。我們無法單獨的責備任何一個瀏覽器；它們都有些問題：</p><ul><li>Firefox</li><li>Chrome (Blink)</li><li>WebKit</li></ul><p>大多數情況下，這些 bug 都是禁止通知中的誤報。所有的瀏覽器提供者都在努力解決這些問題，因此我們可以期待很快就會被解決。無論怎樣，這都不會成為你使用 CSP 的絆腳石。</p><hr>`,15)),n("p",null,[s[27]||(s[27]=e("via: ",-1)),t(a,{href:"https://www.smashingmagazine.com/2016/09/content-security-policy-your-future-best-friend/"},{default:i(()=>[...s[26]||(s[26]=[e("https://www.smashingmagazine.com/2016/09/content-security-policy-your-future-best-friend/",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=e("作者：",-1)),t(a,{href:"https://www.smashingmagazine.com/author/nicolashoffmann/"},{default:i(()=>[...s[28]||(s[28]=[e("Nicolas Hoffmann",-1)])]),_:1}),s[32]||(s[32]=e(" 譯者：",-1)),t(a,{href:"https://github.com/wcnnbdk1"},{default:i(()=>[...s[29]||(s[29]=[e("wcnnbdk1",-1)])]),_:1}),s[33]||(s[33]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[30]||(s[30]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[36]||(s[36]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[34]||(s[34]=[e("LCTT",-1)])]),_:1}),s[37]||(s[37]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[35]||(s[35]=[e("Linux中國",-1)])]),_:1}),s[38]||(s[38]=e(" 榮譽推出",-1))])])}const P=p(c,[["render",g]]);export{k as __pageData,P as default};
